export function slugify(input: string, maxLength = 64): string {
  const slug = input.normalize('NFKD').replace(/[\u0300-\u036f]/g, '').toLowerCase()
    .replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '');
  return slug.slice(0, maxLength).replace(/-+$/, '');
}
```
It strips accents (Café Müller becomes cafe-muller), collapses runs of other characters into one dash, and trims dashes after cutting to 64. Letters like ß and ø don't decompose under NFKD, so I'd add an explicit map or test for them.
